from connected_research_case import ResearchAuthor,present_case
from pathlib import Path
import json

a=ResearchAuthor('ai-7/34')
for old,new in [('Two 45-minute sessions.','Use the three-session teaching cycle above, with extra time as needed.'),('says100','says 100'),('shows18','shows 18'),('to90','to 90'),('over20','over 20'),('says12','says 12'),('has10','has 10'),('and2','and 2'),('with8','with 8')]:
 if old in str(a.w):a.replace_text(old,new)
old_reason='The source-object count, not the photo count, defines the independent plants.'
new_reason='Five source plants have two views each; independence requires a justified sampling design.'
a.replace_text(old_reason,new_reason)
present_case(a,
 headline='Align every manuscript claim with the correct recorded result',
 purpose='Preserve failures, grouping and missing outcomes consistently across abstract, tables, figures and artifacts.',
 intro='A final manuscript is one connected account of question, design, results and limits. Its abstract must not promise more than the tables or records establish. Check each headline against the correct run, denominator and outcome. When a figure omits failures, fix both the figure and the claim; adding a footnote while leaving a false headline is not enough. Distinguish exploratory revisions and unassessed outcomes from the original evaluated set.',
 contract=[['Manuscript item','Complete supplied exercise contract'],['Main raw result','Eighteen passes among twenty evaluated cases; two failures'],['Main inconsistency','Abstract says 100%; figure omits two failures'],['Required main correction','90% over twenty with two failures visible throughout'],['Separate picture','A correct 7/10, B 8/10; all photos indoor'],['Picture grouping','Five plants, two views each; ten photos total'],['Independence evidence','Five identities are not proof of independent sampling'],['Artifact linkage','Each claim points to its actual run, data and version; do not invent identifiers'],['Unknown properties','Population superiority, significance, outdoor performance and detailed case outcomes']],
 ledger=[['Main manuscript location','Current inconsistency','Supported correction'],['Raw results table','18/20','Keep original twenty-case record'],['Abstract','100% success','18/20 = 90% on these evaluated cases'],['Figure','Two failures absent','Restore both failures and total twenty'],['Failure count','Hidden by headline/figure','Two failures explicitly reported'],['Run/artifact references','Need consistency','Identify the actual linked record; no fabricated IDs'],['Broader claim','Not established','Keep case/outcome scope attached']],
 picture='The separate capstone picture compares A seven correct of ten photos and B eight correct of ten: 70% and 80%, a one-photo or ten-percentage-point observed difference. Those ten indoor photos come from five plants with two views each. They are not ten independent plants, and five source identities alone do not establish independent sampling. Report grouping and use analysis assumptions justified for the actual design. No per-case output table is supplied here, so do not invent which photos changed or a plant-level score. A final manuscript can report the supplied photo-level counts while clearly acknowledging indoor coverage, repeated views and absent population/significance evidence.',
 picture_table=[['Separate capstone record','Supported value or limit'],['A photo correctness','7/10 = 70%'],['B photo correctness','8/10 = 80%'],['Observed difference','One correct photo; ten percentage points'],['Source grouping','Five plants × two views = ten photos'],['Setting','Indoor only'],['Ten independent plants claim','Wrong count and unsupported independence premise'],['Five plant identities','Correct source count; sampling independence still needs justification'],['Case-level and plant-level outcomes','Not supplied; do not reconstruct them'],['Outdoor / population / significance','Not established']],
 probes=[['Manuscript audit','Checked interpretation'],['Abstract 100%, raw 18/20','Correct headline to 90%; retain two failures'],['Figure hides failures','Restore them and denominator, not just a caveat'],['One manuscript has multiple runs','Point every table/claim to the correct version'],['Ten photos from five plants','Report repeated source views'],['Plant IDs are distinct','Not automatic sampling independence'],['Raw case-level outputs absent','Do not invent transitions or a plant-level score'],['Two missing cases','Report coverage and unassessed status, not evaluated-as-complete'],['Polished manuscript','Does not create evidence or erase limitations']],
 investigation='Perform a paper consistency audit of the abstract, table, figure and run reference. Repair the main result to eighteen of twenty, ninety percent, with two failures retained in every view. Use actual artifact identifiers only when provided; otherwise mark them not supplied. For the separate picture, connect 7/10 and 8/10 photo counts to five plants with repeated views, correcting the ten-independent-plants claim. Keep independence justification and case-level outputs unresolved rather than inventing them. This exercise edits a fictional manuscript account, not a real experiment. Reserve the independent completed/missing-case summary.',
 teacher_key='Main eighteen of twenty is 90%, with two failures; align abstract, figure, table and actual run record. Picture A 7/10 = 70%, B 8/10 = 80%, gain one photo or ten percentage points. All photos are indoor, from five plants with two views each. Correct ten-independent-plants wording to the actual source grouping, while still requiring sampling independence justification; no invented plant-level rate. Independent twelve eligible records include ten completed, two missing and eight passes: completed-case 8/10 = 80%, coverage 10/12 ≈ 83.333%, two unassessed and two completed failures. The 8/12 = 66.667% known-pass/all-eligible rate is different. Do not call all twelve evaluated or claim population superiority.',
 reference='A final manuscript aligns question, methods, results, limitations and reproducibility artifacts. Main raw result eighteen passes out of twenty evaluated is 90%, not the abstract’s 100%; restore the two failures omitted from the figure and link every view to the correct record/version. Separate picture has A 7/10 = 70%, B 8/10 = 80% on indoor photos, a one-photo or ten-point descriptive gain. Ten photos come from five plants with two views each; report that grouping rather than ten independent plants. Five source IDs alone do not establish sampling independence. Case-level and plant-level outcomes are not supplied, so no invented transitions or plant-level rate are justified. Indoor coverage does not establish outdoor robustness, population superiority or significance. Keep exploratory versions and unassessed outcomes visible. Missing artifact IDs remain unknown. A complete manuscript is a traceable account, not a guarantee that the design or interpretation is valid.',
 independent='Correct the summary using completed-case performance, coverage and explicit missing outcomes, retaining the metric denominator.',
 image={'type':'image','src':'/api/resource/ai-7-34-manuscript-chain','alt':'Main raw record has eighteen passes and two failures among twenty evaluated cases. Figure and table must retain all twenty; the abstract must report ninety percent on this set, not one hundred percent. Separate capstone picture uses ten indoor photos from five plants with two views each.','caption':'Manuscript consistency links each claim to the actual result. Repeated views and evidence limits remain visible.'})
# The old comparison SVG contains the same corrected sentence; preserve its asset ID.
R=Path(__file__).resolve().parents[1];svg=R/'assets/academy-story-ai-7-34-04.svg';text=svg.read_text();assert old_reason in text;svg.write_text(text.replace(old_reason,new_reason))
manifest_path=R/'reports/graphic-journeys.json';manifest=json.loads(manifest_path.read_text())
next(row for row in manifest['weeks'] if row['week']=='ai-7/34')['graphics']=a.w['graphic_story']
manifest_path.write_text(json.dumps(manifest,ensure_ascii=False,indent=2))
(R/'tools/lesson-upgrades/ai-7-34.json').write_text(json.dumps(a.w['pictorial_case'],ensure_ascii=False,indent=2))
